function loadFarmingGame(c){c.innerHTML='<div class="mini-game-container"><h4>🚜 Sustainable Farming Simulator</h4><p><strong>Goal:</strong> Choose fertilizer amount. Too little = poor crops. Too much = water pollution!</p><div class="chart-bar"><div class="chart-label">Fertilizer Amount</div><input type="range" id="fertSlider" min="0" max="100" value="50" oninput="updateFertPreview(this.value)" style="width:100%;margin:10px 0"></div><div id="fertPreview" style="padding:10px;background:#f0f0f0;border-radius:5px;margin:10px 0">Current: 50 units - Balanced approach</div><button class="btn btn-success" onclick="applyFertilizer()">Apply Fertilizer</button><div id="farmResult"></div></div>'}
