let timerInterval;
function loadTimedChallenge(c){c.innerHTML='<div class="mini-game-container"><h4>⏱️ Storm Drain Emergency!</h4><p><strong>You have 60 seconds!</strong> Deploy barriers before pollution reaches the lake!</p><div id="timer" style="font-size:48px;text-align:center;color:#e74c3c;margin:20px 0">60</div><div class="sample-grid"><div class="sample-card" onclick="deployBarrier(this,\'north\')"><div class="icon">🚧</div><div class="label">North Drain</div></div><div class="sample-card" onclick="deployBarrier(this,\'south\')"><div class="icon">🚧</div><div class="label">South Drain</div></div><div class="sample-card" onclick="deployBarrier(this,\'east\')"><div class="icon">🚧</div><div class="label">East Drain</div></div><div class="sample-card" onclick="deployBarrier(this,\'west\')"><div class="icon">🚧</div><div class="label">West Drain</div></div></div><div id="timedResult"></div></div>';let timeLeft=60;timerInterval=setInterval(()=>{timeLeft--;document.getElementById('timer').textContent=timeLeft;if(timeLeft<=0){clearInterval(timerInterval);document.getElementById('timedResult').innerHTML='<div class="test-result warning"><strong>⏰ Time Up!</strong> Some pollution reached the lake.</div><button class="btn btn-success" onclick="completeChapter()">Continue</button>'}},1000)}
