function showNextStudent(){const tests=[{name:'Emma',ph:7.2,correct:true},{name:'Carlos',ph:14.5,correct:false},{name:'Aisha',ph:6.8,correct:true}];if(trainedStudents>=tests.length){document.getElementById('studentTests').innerHTML+='<div class="test-result good"><strong>✅ Training Complete!</strong> All students certified!</div><button class="btn btn-success" onclick="completeChapter()">Continue</button>';return}const t=tests[trainedStudents];document.getElementById('studentTests').innerHTML=`<div class="dialogue-box"><div class="dialogue-character"><div class="character-avatar">👤</div><div class="character-name">${t.name}</div></div><div class="dialogue-text">I measured pH: ${t.ph}</div><div class="choice-buttons"><div class="choice-btn" onclick="reviewTest(true,${t.correct})">✅ Approve</div><div class="choice-btn" onclick="reviewTest(false,${t.correct})">❌ Reject & Retrain</div></div></div>`}
