function legalArgument(arg,strong){if(strong){legalPoints++;document.getElementById('debateResult').innerHTML+=`<div class="test-result good"><strong>✅ Strong Argument!</strong> ${arg} accepted by court</div>`}else{document.getElementById('debateResult').innerHTML+=`<div class="test-result warning"><strong>⚠️ Weak Argument!</strong> ${arg} dismissed</div>`}if(legalPoints>=2){document.getElementById('debateResult').innerHTML+='<div class="test-result good"><strong>🎉 Case Won!</strong> Factory ordered to clean up!</div><button class="btn btn-success" onclick="completeChapter()">Victory!</button>';gameState.trustLevel+=40;updateStats()}}

