function loadDroughtGame(c){c.innerHTML='<div class="mini-game-container"><h4>🏜️ Drought Crisis Management</h4><p><strong>Allocate scarce water resources:</strong></p><div class="choice-buttons"><div class="choice-btn" onclick="allocateWater(\'drinking\',40)"><strong>🚰 Drinking Water:</strong> 40% to humans</div><div class="choice-btn" onclick="allocateWater(\'farming\',30)"><strong>🌾 Agriculture:</strong> 30% to farms</div><div class="choice-btn" onclick="allocateWater(\'ecosystem\',30)"><strong>🐟 Ecosystem:</strong> 30% to river</div></div><div id="droughtResult"></div></div>'}
