function loadSummitGame(c){c.innerHTML='<div class="mini-game-container"><h4>🏛️ UN Global Summit</h4><p><strong>Present to world leaders. Choose your key messages:</strong></p><div class="choice-buttons"><div class="choice-btn" onclick="summitMessage(\'local\')"><strong>🏘️ Local Action:</strong> Communities can solve problems</div><div class="choice-btn" onclick="summitMessage(\'science\')"><strong>🔬 Science Works:</strong> Data drives decisions</div><div class="choice-btn" onclick="summitMessage(\'hope\')"><strong>🌟 Hope Exists:</strong> Change is possible</div><div class="choice-btn" onclick="summitMessage(\'urgent\')"><strong>⏰ Urgency:</strong> Act now, not later</div></div><div id="summitResult"></div></div>'}
